{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section heading identifying the regulation as 29 CFR 825.110, regarding eligible employees under the FMLA, containing no substantive legal requirement in itself."
    },
    {
      "quote_ref": "F002",
      "scope_refs": ["F001"],
      "kind": "condition",
      "meaning": "To be an eligible employee under the FMLA, an employee of a covered employer must have been employed by the employer for at least 12 months."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F001"],
      "kind": "condition",
      "meaning": "To be an eligible employee under the FMLA, an employee of a covered employer must have been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of the leave, subject to special hours of service requirements for airline flight crew employees under 29 CFR 825.801."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F001"],
      "kind": "condition",
      "meaning": "To be an eligible employee under the FMLA, an employee of a covered employer must be employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite (referencing 29 CFR 825.105(b) regarding employees working outside the U.S.)."
    },
    {
      "quote_ref": "F005",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The 12 months of employment required for an employee to be eligible under the FMLA do not need to be consecutive months."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F005"],
      "kind": "permission",
      "meaning": "Subject to the exceptions in paragraph (b)(2), employment periods prior to a break in service of seven years or more do not need to be counted in determining whether an employee has been employed by the employer for at least 12 months."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F005", "F007"],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed for at least 12 months if the break in service is occasioned by the fulfillment of the employee's USERRA-covered service obligation; the period of absence from work due to or necessitated by USERRA-covered service must also be counted, though this section confers no greater entitlement than is available under USERRA."
    },
    {
      "quote_ref": "F009",
      "scope_refs": ["F005", "F007"],
      "kind": "requirement",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed for at least 12 months where a written agreement, including a collective bargaining agreement, exists concerning the employer's intention to rehire the employee after the break in service (such as for education or childrearing purposes)."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F005"],
      "kind": "definition",
      "meaning": "If an employee is maintained on the payroll for any part of a week, including any periods of paid or unpaid leave (such as sick or vacation) during which other benefits or compensation are provided by the employer (such as workers' compensation or group health plan benefits), that entire week counts as a week of employment; for intermittent, occasional, or casual employment, 52 weeks is deemed equal to 12 months."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F005"],
      "kind": "permission",
      "meaning": "Employers are permitted to consider an employee's employment prior to a continuous break in service of more than seven years when determining whether the 12-month requirement is met, but if an employer chooses to recognize such prior employment, it must do so uniformly with respect to all employees with similar breaks in service."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Except as provided in paragraph (c)(2) and 29 CFR 825.801 for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to FLSA principles for compensable hours of work (29 CFR part 785); the determining factor is the actual hours worked within the FLSA definition, without limitation by recordkeeping methods or inaccurate compensation agreements, and any accurate accounting of actual hours worked under FLSA principles may be used."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employee returning from or reemployed following USERRA-covered service must be credited with the hours of service that would have been performed but for the period of absence due to or necessitated by that service, adding them to hours actually worked during the previous 12-month period to satisfy the 1,250-hour requirement; calculations can generally use the employee's pre-service work schedule (subject to 29 CFR 825.801(c) for airline flight crew employees)."
    },
    {
      "quote_ref": "F014",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "If an employer does not maintain an accurate record of hours worked by an employee—including employees exempt from FLSA recordkeeping requirements (such as executive, administrative, and professional employees)—the employer carries the burden of showing that the employee has not worked the required hours (for example, being able to clearly demonstrate that full-time teachers did not work 1,250 hours in the previous 12 months to deny eligibility; subject to 29 CFR 825.801(d) for airline flight crew employees)."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The determination of whether an employee meets the hours of service requirement and has at least 12 months of total employment must be made as of the date the FMLA leave is to start; if an employee is on non-FMLA leave when the 12-month eligibility requirement is reached, any portion of the leave taken for an FMLA-qualifying reason after meeting eligibility is FMLA leave (referencing 29 CFR 825.300(b) for eligibility notice content)."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Whether 50 employees are employed within 75 miles is determined when the employee gives notice of the need for leave; once determined eligible in response to that notice, eligibility for that specific notice is not affected by subsequent employee count changes regardless of whether leave is continuous, intermittent, or reduced schedule; an employer may not terminate leave that has already started if employee count falls below 50, and must grant FMLA benefits if notice is given when 50 or more employees are employed (e.g., notice in August with 60 employees for leave beginning in December when count is expected to drop to 40)."
    }
  ]
}
